pub fn exact_html_json_for_column(column_number: i64) -> Option<&'static str> {
    EXACT_HTML_META_JSON.iter().find(|(c, _)| *c == column_number).map(|(_, s)| *s)
}

pub fn all_exact_html_json() -> impl Iterator<Item = (i64, &'static str)> {
    EXACT_HTML_META_JSON.iter().copied()
}
